const rows = $input.all().map((i) => i.json);
const summary = rows.find((r) => r && (r.ghostwriterSwipePrompt || r.insights || r.topHooks)) || {};
const notes = rows.filter((r) => r && (r.noteId || r.hook || r.viralScore !== undefined));
const outliers3x = notes
  .filter((n) => Number(n.outlierMultiplier || 0) >= 3)
  .sort((a, b) => Number(b.outlierMultiplier || 0) - Number(a.outlierMultiplier || 0) || Number(b.viralScore || 0) - Number(a.viralScore || 0))
  .map((n) => ({
    handle: n.handle,
    authorName: n.authorName,
    hook: n.hook,
    viralScore: n.viralScore,
    outlierMultiplier: n.outlierMultiplier,
    lengthBucket: n.lengthBucket,
    wordCount: n.wordCount,
    noteUrl: n.noteUrl,
    agentSummary: n.agentSummary,
  }));
const fallbackPrompt = outliers3x.length
  ? "Reverse-engineer these >=3x Substack Notes outliers (structure, opening hook, pacing) and write 5 original variants:\n\n" + outliers3x.slice(0, 8).map((o, idx) => `${idx + 1}. [${o.outlierMultiplier}x | ${o.lengthBucket}] ${o.hook} (${o.noteUrl})`).join("\n")
  : "No >=3x outlier notes found in this batch.";
return [{
  json: {
    totalNotesScanned: notes.length,
    outliers3xCount: outliers3x.length,
    insights: summary.insights || null,
    ghostwriterSwipePrompt: summary.ghostwriterSwipePrompt || fallbackPrompt,
    outliers3x,
  },
}];
